import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Developer Guide","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/index.md","filePath":"dev-guide/index.md","lastUpdated":1788334237000}'),i={name:"dev-guide/index.md"};function d(n,e,c,l,s,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="developer-guide" tabindex="-1">Developer Guide <a class="header-anchor" href="#developer-guide" aria-label="Permalink to &quot;Developer Guide&quot;">​</a></h1><p>Welcome to the Lertaro Developer Reference Manual. Built upon a decoupled multi-process architecture and an extensible plugin ecosystem, Lertaro provides an official SDK assembly: <code>Lertaro.PluginSdk</code>. By referencing this SDK, third-party developers can contribute custom search sources, extend context action menus, deeply integrate with third-party file managers and native file dialogs, and customize themes and preview handlers.</p><h2 id="_1-architecture-workflow" tabindex="-1">1. Architecture &amp; Workflow <a class="header-anchor" href="#_1-architecture-workflow" aria-label="Permalink to &quot;1. Architecture &amp; Workflow&quot;">​</a></h2><ul><li><strong><a href="./architecture.html">System Architecture</a></strong> —— Deep dive into the three-process isolation model (SYSTEM-level Windows Service, user-mode WPF App, and keyboard Hook process) and named pipe IPC.</li><li><strong><a href="./getting-started.html">Getting Started</a></strong> —— Step-by-step guide to creating a plugin class library, referencing the SDK, implementing <code>IPlugin</code>, and local debugging.</li><li><strong><a href="./packaging.html">Packaging &amp; Distribution</a></strong> —— Assembly directory conventions, bundling third-party managed/native DLLs, embedding i18n resources, and PostBuild deployment automation.</li><li><strong><a href="./examples.html">Plugin Examples</a></strong> —— Real-world case studies analyzing the official open-source <code>CoreExtensions</code>, <code>PinyinAlias</code>, and <code>FlowLauncherBridge</code> plugins.</li></ul><h2 id="_2-plugin-sdk-reference" tabindex="-1">2. Plugin SDK Reference <a class="header-anchor" href="#_2-plugin-sdk-reference" aria-label="Permalink to &quot;2. Plugin SDK Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">SDK Category</th><th style="text-align:left;">Core Interfaces &amp; Services</th><th style="text-align:left;">Key Capabilities</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">Core Search &amp; Actions</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IFullSearchFileResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">Contribute indexed items, instant calculation answers, Full Search Window file results, non-ASCII alias transliteration engines, query suffix token handlers, and static/dynamic context action menus.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">System &amp; Dialog Adapters</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">Detect active directories in file managers, hook native file dialogs, embed inline search bars with two-way selection sync, and provide Quick Navigation cascading menus.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">UI &amp; Preview Extensions</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">Add sidebar filter categories, custom table columns, Quick Panel dynamic workspace tabs, QuickLook custom preview renderers, thumbnail extractors, WPF themes, and i18n language packs.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">Shared Abstractions</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">Read-only result models, high-precision file timestamps and size metadata, host window control handles, and schema-driven native configuration forms.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">Host Services</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SettingsSearchService</code><br><code>SettingsWindowService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">High-performance host infrastructure: fzf fuzzy matching and highlight masks, cached icon extraction, favorite management, directory indexer proxies, data directory isolation, and native Shell file operations.</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>All interface signatures, method parameters, and behavioral contracts in this manual have been verified directly against the <code>Lertaro.PluginSdk</code> source code.</p></div>',7)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
